import { FolderGit2, FolderPlus, LayoutDashboard, PanelLeftClose, Plus, Search, Settings2 } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { shortcutLabel } from "../lib/shortcuts";
import type { RegisteredProject } from "../lib/tauri";
import type { ActiveAgent, DirtyState, Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { SectionHeader } from "./ui/SectionHeader";
import { WorktreeList } from "./WorktreeList";

export const SIDEBAR_WIDTH_STORAGE_KEY = "orca.sidebar.width";
const DEFAULT_SIDEBAR_WIDTH = 236;
const MIN_SIDEBAR_WIDTH = 220;
const MAX_SIDEBAR_WIDTH = 420;

type SidebarProps = {
  projects?: RegisteredProject[];
  activeProjectId?: string;
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  statuses?: Record<string, DirtyState | undefined>;
  onSelectProject?: (project: RegisteredProject) => void;
  onAddProject?: () => void;
  onSelectWorktree: (worktree: Worktree) => void;
  onCreateWorktree: () => void;
  onRefreshWorktreeStatus?: (worktree: Worktree) => void;
  onDeleteWorktree?: (worktree: Worktree) => void;
  onOpenCommandPalette: () => void;
  onOpenSettings?: () => void;
};

export function Sidebar({
  projects = [],
  activeProjectId,
  worktrees,
  agents,
  activePath,
  statuses = {},
  onSelectProject = () => undefined,
  onAddProject = () => undefined,
  onSelectWorktree,
  onCreateWorktree,
  onRefreshWorktreeStatus = () => undefined,
  onDeleteWorktree = () => undefined,
  onOpenCommandPalette,
  onOpenSettings,
}: SidebarProps) {
  const worktreeRegionRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const [width, setWidth] = useState(loadSidebarWidth);
  const widthRef = useRef(width);
  widthRef.current = width;

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const nextWidth = clampSidebarWidth(drag.startWidth + event.clientX - drag.startX);
      widthRef.current = nextWidth;
      setWidth(nextWidth);
    };

    const finishDrag = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      persistSidebarWidth(widthRef.current);
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, []);

  const focusWorktrees = () => {
    worktreeRegionRef.current?.focus();
    worktreeRegionRef.current?.scrollIntoView?.({ block: "start" });
  };

  const startResize = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    dragRef.current = { startX: event.clientX, startWidth: widthRef.current };
    document.body.style.cursor = "col-resize";
  };

  return (
    <aside
      className="relative flex h-full shrink-0 flex-col overflow-hidden bg-worktree-sidebar text-worktree-sidebar-foreground"
      style={{ width: `${width}px`, minWidth: `${MIN_SIDEBAR_WIDTH}px`, maxWidth: `${MAX_SIDEBAR_WIDTH}px` }}
    >
      <div
        data-testid="sidebar-drag-region"
        data-tauri-drag-region
        className="drag-region flex h-titlebar shrink-0 items-center justify-end px-2"
      >
        <IconButton label="Hide sidebar" className="no-drag" size="sm">
          <PanelLeftClose className="size-3.5" />
        </IconButton>
      </div>

      <div className="space-y-1 px-2 pb-1">
        <button
          type="button"
          onClick={focusWorktrees}
          className="flex h-7 w-full items-center gap-2 rounded-md bg-worktree-sidebar-accent px-2 text-left text-[13px] font-medium tracking-tight text-worktree-sidebar-accent-foreground"
        >
          <LayoutDashboard className="size-3.5" />
          <span className="flex-1">Workspace</span>
        </button>
        <button
          type="button"
          onClick={onOpenCommandPalette}
          className="group relative flex h-7 w-full items-center rounded-md border border-worktree-sidebar-border/70 bg-worktree-sidebar-foreground/5 pl-7 pr-1.5 text-left text-[12px] font-medium tracking-tight text-worktree-sidebar-foreground/45 transition-colors hover:border-worktree-sidebar-border hover:bg-worktree-sidebar-foreground/8"
        >
          <Search className="pointer-events-none absolute left-2 top-1/2 size-3 -translate-y-1/2 text-worktree-sidebar-foreground/30" />
          Search workspaces
          <kbd className="ml-auto rounded border border-worktree-sidebar-border/80 bg-worktree-sidebar-foreground/8 px-1 py-px text-[9px] text-worktree-sidebar-foreground/55">
            {shortcutLabel("commandPalette.open")}
          </kbd>
        </button>
      </div>

      <div className="shrink-0 border-b border-worktree-sidebar-border pb-1">
        <SectionHeader
          title="Projects"
          count={projects.length}
          actions={
            <IconButton label="Add project" size="sm" onClick={onAddProject}>
              <Plus className="size-3.5" />
            </IconButton>
          }
        />
        <div className="space-y-0.5 px-2">
          {projects.map((project) => {
            const active = project.workspaceId === activeProjectId;
            return (
              <button
                key={project.workspaceId}
                type="button"
                onClick={() => onSelectProject(project)}
                className={`flex h-7 w-full items-center gap-2 rounded-md px-2 text-left text-[12px] transition-colors ${
                  active
                    ? "bg-worktree-sidebar-accent text-worktree-sidebar-accent-foreground"
                    : "text-worktree-sidebar-foreground/65 hover:bg-worktree-sidebar-accent/60 hover:text-worktree-sidebar-foreground"
                }`}
              >
                <FolderGit2 className="size-3.5 shrink-0" />
                <span className="min-w-0 flex-1 truncate">{project.workspaceId}</span>
              </button>
            );
          })}
        </div>
      </div>

      <div ref={worktreeRegionRef} tabIndex={-1} data-testid="worktree-region" className="flex min-h-0 flex-1 flex-col outline-none">
        <SectionHeader
          title="Worktrees"
          count={worktrees.length}
          actions={
            <IconButton label="Add worktree" size="sm" onClick={onCreateWorktree}>
              <FolderPlus className="size-3.5" />
            </IconButton>
          }
        />
        <WorktreeList
          worktrees={worktrees}
          agents={agents}
          activePath={activePath}
          statuses={statuses}
          onSelect={onSelectWorktree}
          onCreate={onCreateWorktree}
          onRefreshStatus={onRefreshWorktreeStatus}
          onDelete={onDeleteWorktree}
        />
      </div>

      <div className="flex shrink-0 items-center justify-between border-t border-worktree-sidebar-border px-2 py-1.5">
        <div className="flex items-center gap-2 px-1 text-[10px] text-muted-foreground">
          <span className="size-1.5 rounded-full bg-status-success" />
          Local runtime
        </div>
        <IconButton label="Settings" size="sm" onClick={onOpenSettings}>
          <Settings2 className="size-3.5" />
        </IconButton>
      </div>

      <div
        role="separator"
        aria-label="Resize sidebar"
        aria-orientation="vertical"
        aria-valuemin={MIN_SIDEBAR_WIDTH}
        aria-valuemax={MAX_SIDEBAR_WIDTH}
        aria-valuenow={width}
        onPointerDown={startResize}
        className="no-drag absolute inset-y-0 right-0 z-30 w-1.5 cursor-col-resize touch-none"
      >
        <span className="pointer-events-none absolute inset-y-0 right-0 w-px bg-worktree-sidebar-border transition-colors group-hover:bg-ring/45" />
      </div>
    </aside>
  );
}

function loadSidebarWidth() {
  try {
    const stored = Number(window.localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY));
    return Number.isFinite(stored) && stored > 0 ? clampSidebarWidth(stored) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

function persistSidebarWidth(width: number) {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(width)));
  } catch {
    // A storage failure should not break pointer resizing for this session.
  }
}

function clampSidebarWidth(width: number) {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, Math.round(width)));
}

import { ChevronDown, GitBranch, LockKeyhole, Plus, RefreshCcw, Trash2 } from "lucide-react";

import { cn } from "../lib/cn";
import { worktreeIdentity, type ActiveAgent, type DirtyState, type Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { StatusDot } from "./ui/StatusDot";

type WorktreeListProps = {
  worktrees: Worktree[];
  activePath: string;
  agents: ActiveAgent[];
  statuses: Record<string, DirtyState | undefined>;
  onSelect: (worktree: Worktree) => void;
  onCreate: () => void;
  onRefreshStatus: (worktree: Worktree) => void;
  onDelete: (worktree: Worktree) => void;
};

function basename(path: string) {
  if (path === ".") return "main";
  return path.split(/[\\/]/).filter(Boolean).at(-1) ?? path;
}

function branchName(worktree: Worktree) {
  return worktree.branch?.replace(/^refs\/heads\//, "") ?? "detached HEAD";
}

function workspaceName(worktree: Worktree) {
  const parts = branchName(worktree).split("/");
  return parts[0] === "orca" && parts.length > 2 ? parts.slice(2).join("/") : basename(worktree.path);
}

export function WorktreeList({
  worktrees,
  activePath,
  agents,
  statuses,
  onSelect,
  onCreate,
  onRefreshStatus,
  onDelete,
}: WorktreeListProps) {
  const rootName = worktrees[0]?.path && worktrees[0].path !== "."
    ? (worktrees[0].path.split("/").pop() || "Workspace")
    : "Workspace";

  return (
    <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-1 pb-2 scrollbar-sleek">
      <div className="sticky top-0 z-10 flex h-7 items-center gap-1.5 bg-worktree-sidebar pr-2 text-left">
        <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
          <ChevronDown className="size-3.5" />
        </span>
        <span className="min-w-0 flex-1 truncate text-[11px] font-semibold text-foreground">{rootName}</span>
        <IconButton label="New worktree" size="sm" onClick={onCreate}>
          <Plus className="size-3.5" />
        </IconButton>
      </div>

      <div className="pl-3 pr-1">
        {worktrees.length === 0 ? (
          <div className="border-l border-worktree-sidebar-border px-3 py-3 text-[10px] leading-relaxed text-muted-foreground">
            No Git worktrees found for this repository.
          </div>
        ) : null}

        {worktrees.map((worktree) => {
          const active = worktree.path === activePath;
          const agent = agents.find((candidate) => candidate.worktreePath === worktree.path);
          const status = statuses[worktree.path];
          const canDelete = worktreeIdentity(worktree) !== null;
          return (
            <div
              key={worktree.path}
              className={cn(
                "group/worktree-row relative w-full border-l border-transparent transition-colors",
                active
                  ? "border-worktree-sidebar-ring/60 bg-worktree-sidebar-accent"
                  : "hover:bg-worktree-sidebar-accent/45",
              )}
            >
              <button type="button" onClick={() => onSelect(worktree)} className="w-full px-2 py-1.5 pr-14 text-left">
                <span className="flex min-w-0 items-start gap-1.5">
                  <span className="mt-0.5 flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                    <GitBranch className="size-3" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="flex items-center gap-1.5">
                      {agent ? <StatusDot state={agent.state} /> : <span className="size-1.5 rounded-full bg-status-idle" />}
                      <span className="min-w-0 flex-1 truncate text-[12px] font-medium leading-tight text-foreground">
                        {workspaceName(worktree)}
                      </span>
                    </span>
                    <span className="mt-0.5 block truncate font-mono text-[9px] leading-snug text-muted-foreground/75">
                      {branchName(worktree)}
                    </span>
                    <span className={cn("mt-0.5 block text-[9px]", status?.isDirty ? "text-status-warning" : "text-muted-foreground/75")}>
                      {status ? (status.isDirty ? `Dirty · ${status.files.length} ${status.files.length === 1 ? "file" : "files"}` : "Clean") : "Status not checked"}
                    </span>
                    {agent ? (
                      <span className="mt-0.5 flex items-center gap-1.5 truncate text-[9px] text-muted-foreground/75">
                        <span className="truncate">{agent.name}</span>
                        <span aria-hidden="true">·</span>
                        <span className="truncate">{agent.task}</span>
                      </span>
                    ) : null}
                  </span>
                </span>
              </button>

              <div className="absolute right-1 top-1 flex items-center gap-0.5 opacity-55 transition-opacity group-hover/worktree-row:opacity-100 focus-within:opacity-100">
                {worktree.locked ? <LockKeyhole className="mr-0.5 size-3 text-status-warning" /> : null}
                <IconButton label="Refresh worktree status" size="sm" onClick={() => onRefreshStatus(worktree)}>
                  <RefreshCcw className="size-3" />
                </IconButton>
                <IconButton label="Delete worktree" size="sm" disabled={!canDelete} onClick={() => onDelete(worktree)}>
                  <Trash2 className="size-3" />
                </IconButton>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

