import type { ButtonHTMLAttributes, ReactNode } from "react";

import { cn } from "../../lib/cn";

type IconButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  label: string;
  children: ReactNode;
  size?: "sm" | "md";
};

export function IconButton({
  label,
  children,
  className,
  size = "md",
  type = "button",
  ...props
}: IconButtonProps) {
  return (
    <button
      type={type}
      aria-label={label}
      title={label}
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors",
        "hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
        "disabled:pointer-events-none disabled:opacity-40",
        size === "sm" ? "size-6" : "size-7",
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
}
import type { ReactNode } from "react";

import { cn } from "../../lib/cn";

type SectionHeaderProps = {
  title: string;
  count?: number;
  actions?: ReactNode;
  className?: string;
};

export function SectionHeader({ title, count, actions, className }: SectionHeaderProps) {
  return (
    <div className={cn("flex h-8 items-center justify-between gap-2 px-2", className)}>
      <div className="flex min-w-0 items-center gap-1.5 pl-2 text-xs font-semibold text-muted-foreground/80">
        <span className="truncate">{title}</span>
        {count !== undefined ? (
          <span className="rounded-full bg-sidebar-accent px-1.5 py-0.5 text-[10px] leading-none text-muted-foreground">
            {count}
          </span>
        ) : null}
      </div>
      {actions ? <div className="flex shrink-0 items-center gap-1">{actions}</div> : null}
    </div>
  );
}
import { CheckCircle2, CircleX, MessageCircleQuestion } from "lucide-react";

import { cn } from "../../lib/cn";
import type { AgentState } from "../../lib/types";

type StatusDotProps = {
  state: AgentState;
  className?: string;
};

export function StatusDot({ state, className }: StatusDotProps) {
  if (state === "working") {
    return (
      <span className={cn("relative inline-flex size-3 shrink-0 items-center justify-center", className)}>
        <span className="absolute size-3 animate-ping rounded-full bg-status-working/25 motion-reduce:animate-none" />
        <span className="size-2 rounded-full bg-status-working" />
      </span>
    );
  }

  if (state === "starting") {
    return <span className={cn("size-2 shrink-0 animate-pulse rounded-full bg-status-warning motion-reduce:animate-none", className)} />;
  }

  if (state === "waiting") {
    return <MessageCircleQuestion className={cn("size-3 shrink-0 text-status-warning", className)} />;
  }

  if (state === "exited") {
    return <CheckCircle2 className={cn("size-3 shrink-0 text-status-success", className)} />;
  }

  return <CircleX className={cn("size-3 shrink-0 text-destructive", className)} />;
}
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

export type TerminalSignal = "interrupt" | "terminate" | "kill";

export type TerminalSessionSummary = {
  sessionId: string;
  worktreePath: string | null;
};

export type TerminalLifecycle = "starting" | "working" | "waiting" | "exited" | "failed";

export type TerminalSession = {
  id: string;
  cwd: string;
  workspaceId: string;
  worktree: WorktreeIdentity | null;
  backendSessionId: string | null;
  lifecycle: TerminalLifecycle;
  ownerId?: string | null;
};

export type TerminalTab = {
  id: string;
  label: string;
  sessionId: string;
};

export type Pane = {
  id: string;
  tabId: string;
};

export type SplitMode = "none" | "horizontal" | "vertical";

export type NestedSplit = {
  orientation: Exclude<SplitMode, "none">;
  tabId: string;
};

export type LayoutState = {
  tabs: TerminalTab[];
  primaryTabId: string | null;
  secondaryTabId: string | null;
  split: SplitMode;
  nestedSplit: NestedSplit | null;
};

export type AgentState = "starting" | "working" | "waiting" | "exited" | "failed";

export type ActiveAgent = {
  id: string;
  name: string;
  task: string;
  state: AgentState;
  worktree: WorktreeIdentity | null;
  worktreePath: string;
  sessionId: string;
};

export type TerminalOutputPayload = {
  sessionId: string;
  data: string;
};

export type TerminalLifecyclePayload = {
  sessionId: string;
  state: "started" | "exited" | "failed";
  exitCode: number | null;
  reason: string | null;
};

export type WorktreeChangedPayload = {
  workspaceId: string;
  worktree: WorktreeIdentity;
