      const tag = el.tagName.toLowerCase();
      const own = Array.from(el.childNodes).filter(n => n.nodeType === 3).map(n => n.textContent?.trim()).filter(Boolean).join(" ");
      const exp = el.getAttribute("aria-expanded");
      const cur = el.getAttribute("aria-current");
      const lbl = el.getAttribute("aria-label");
      if (["button","ul","li","span"].includes(tag) && (own || exp || lbl))
        console.log("  ".repeat(d) + `<${tag}${exp?` expanded=${exp}`:""}${cur?` current=${cur}`:""}${lbl?` label="${lbl}"`:""}> ${own}`);
      Array.from(el.children).forEach(c => walk(c, d + 1));
    };
    walk(screen.getByRole("complementary"));
    expect(true).toBe(true);
  });
});
